begin;lock table public.campaigns,public.campaign_content_entries,public.campaign_state_fragments,public.campaign_character_versions,public.official_content_entries in share row exclusive mode;do $native$ begin if(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')<>1738 then raise exception 'NATIVE_CAMPAIGN_CHANGED';end if;if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:7d150b153865ce199ca4823c' and md5(to_jsonb(t)::text)='d20656d88f1eff8f7ae2c07e128084bc')then raise exception 'NATIVE_DEFINITION_CHANGED:official:equipment:es:7d150b153865ce199ca4823c';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(payload,'{rules,definition}',$native_7950db20418516b0${"format":"equipment-definition-draft","schemaVersion":1,"id":"recovery:official:equipment:es:7d150b153865ce199ca4823c","revision":1,"language":"es","name":"Amuleto","aliases":["Amulet"],"baseDefinitionId":null,"origin":"official","sources":[{"id":"original:a80a26952f8ba6084e5b441b4bd5a86a35cde5d9a342490246d92a9ff59bd1ba","kind":"legacy","title":"Amuleto","language":"es","rulesEdition":null,"locator":"official:equipment:es:7d150b153865ce199ca4823c","verified":false},{"id":"original:8211fa036dc60422d501c2225ac27caa9ec09fd4dbd8b9fb4bb76830471fa3f4","kind":"legacy","title":"Amuleto","language":"es","rulesEdition":null,"locator":"official:equipment:es:7d150b153865ce199ca4823c","verified":false},{"id":"original:0d6feb63ed466a332e9183ed429adfa27a4cb003a6bfd5c6e462fce5ba3051fd","kind":"legacy","title":"Amulet","language":"en","rulesEdition":null,"locator":"official:equipment:eng:f7f6866e4a57c65faedf1e54","verified":false},{"id":"original:46da24859b8077dd5f768d626d0a9afe599cdd82a7d0997da2deec31ff89eae5","kind":"legacy","title":"Amulet","language":"en","rulesEdition":null,"locator":"official:equipment:eng:f7f6866e4a57c65faedf1e54","verified":false},{"id":"srd-5.1-es-equipment","kind":"srd","title":"Documento de referencia del sistema 5.1 · edición oficial española","language":"es","rulesEdition":"2014","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1_ES.pdf · página PDF 70 · CC-BY-4.0","verified":true},{"id":"srd-5.1-en-equipment","kind":"srd","title":"Documento de referencia del sistema 5.1 · original inglés","language":"en","rulesEdition":"2014","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1.pdf · página PDF 69 · CC-BY-4.0","verified":true},{"id":"srd-5.1-attribution","kind":"srd","title":"Atribución y licencia del SRD 5.1","language":"es","rulesEdition":"2014","locator":"Esta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es. Adaptaciones: separación de párrafos y tablas, datos estructurados y traducciones propias identificadas en cada bloque.","verified":true}],"category":"adventuring-gear","subtypes":[],"magical":false,"rarity":"none","consumable":false,"properties":[],"weight":{"value":1,"unit":"lb"},"economy":{"basePrice":{"quantity":5,"unit":"gp"},"campaignPrice":null,"explanation":"Precio oficial de 2014. No sobrescribe precios propios de personajes o comerciantes."},"description":[{"id":"official-table","section":"description","provenance":"reviewed-translation","sourceIds":["srd-5.1-en-equipment"],"type":"table","columns":["Objeto","Precio base","Peso"],"rows":[["Amuleto","5 po","1 lb"]]},{"id":"official-rules-0","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Símbolo sagrado. Un símbolo sagrado es la representación de un dios o un panteón. Puede tratarse de un amuleto con la forma del dios, o del mismo símbolo, pero cuidadosamente grabado o esculpido en un escudo, o de una cajita que contenga un fragmento de una reliquia sagrada. El apéndice MJ-B, “Panteones histórico-fantásticos”, indica los símbolos que normalmente se asocian a los muchos dioses de multiverso. Un clérigo o un paladín puede utilizar un símbolo sagrado como canalizador mágico. Para ello, el lanzador deberá sostener el símbolo en la mano, llevarlo bien visible en alguna parte del cuerpo o sujetar un escudo que lo tenga grabado."}],"requirements":{"attunement":false,"bearer":[],"presence":"possessed","explanation":"No requiere sintonización."},"weapon":null,"armor":null,"resources":[],"capabilities":[{"id":"mundane-use","name":"Uso del objeto","activation":"passive","trigger":"","requirements":{"attunement":false,"bearer":[],"presence":"possessed","explanation":"No requiere sintonización."},"target":"Portador","range":"","duration":"Mientras se cumplen los requisitos.","concentration":false,"costs":[],"consumeQuantity":0,"effects":[{"id":"table-use","kind":"narrative","condition":"","instructions":"Objeto · Precio base · Peso\nAmuleto · 5 po · 1 lb\n\nSímbolo sagrado. Un símbolo sagrado es la representación de un dios o un panteón. Puede tratarse de un amuleto con la forma del dios, o del mismo símbolo, pero cuidadosamente grabado o esculpido en un escudo, o de una cajita que contenga un fragmento de una reliquia sagrada. El apéndice MJ-B, “Panteones histórico-fantásticos”, indica los símbolos que normalmente se asocian a los muchos dioses de multiverso. Un clérigo o un paladín puede utilizar un símbolo sagrado como canalizador mágico. Para ello, el lanzador deberá sostener el símbolo en la mano, llevarlo bien visible en alguna parte del cuerpo o sujetar un escudo que lo tenga grabado.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."}],"execution":{"mode":"narrative","handler":null,"explanation":"Uso físico o narrativo según las reglas del objeto.","pendingAutomation":[]},"textBlockIds":["official-rules-0"]}],"recoverySourceIds":["a80a26952f8ba6084e5b441b4bd5a86a35cde5d9a342490246d92a9ff59bd1ba","8211fa036dc60422d501c2225ac27caa9ec09fd4dbd8b9fb4bb76830471fa3f4","0d6feb63ed466a332e9183ed429adfa27a4cb003a6bfd5c6e462fce5ba3051fd","46da24859b8077dd5f768d626d0a9afe599cdd82a7d0997da2deec31ff89eae5"],"review":{"identity":true,"information":false,"editorial":true,"mechanics":false,"unresolved":["Cerrar la cobertura de los datos y diferencias antiguos antes de migrar o retirar versiones; las copias y precios comerciales siguen intactos."]}}$native_7950db20418516b0$::jsonb,true),'{features}',$native_20d6da3fc6e17a06$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Símbolo sagrado. Un símbolo sagrado es la representación de un dios o un panteón. Puede tratarse de un amuleto con la forma del dios, o del mismo símbolo, pero cuidadosamente grabado o esculpido en un escudo, o de una cajita que contenga un fragmento de una reliquia sagrada. El apéndice MJ-B, “Panteones histórico-fantásticos”, indica los símbolos que normalmente se asocian a los muchos dioses de multiverso. Un clérigo o un paladín puede utilizar un símbolo sagrado como canalizador mágico. Para ello, el lanzador deberá sostener el símbolo en la mano, llevarlo bien visible en alguna parte del cuerpo o sujetar un escudo que lo tenga grabado.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$native_20d6da3fc6e17a06$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:7d150b153865ce199ca