if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:7e70af915a0f0151f102d0a1' and md5(to_jsonb(t)::text)='661f330a2dc2e91aad0de0ec3bed4293')then raise exception 'NATIVE_DEFINITION_CHANGED:official:equipment:es:7e70af915a0f0151f102d0a1';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(payload,'{rules,definition}',$native_96e1f6556455bd29${"format":"equipment-definition-draft","schemaVersion":1,"id":"recovery:official:equipment:es:7e70af915a0f0151f102d0a1","revision":2,"language":"es","name":"Herramientas de cartógrafo","aliases":["Herramientas del cartógrafo","Cartographer's Tools"],"baseDefinitionId":null,"origin":"official","sources":[{"id":"original:10bcbc744d950a7244dea4801481756d331519b080af89e385fe7146e37b6475","kind":"legacy","title":"Herramientas del cartógrafo","language":"es","rulesEdition":null,"locator":"official:equipment:es:7e70af915a0f0151f102d0a1","verified":false},{"id":"original:3e037aff6d87e89591c61912cd78087c5c6cd36f1d7925f2ef8ff0e3938d5957","kind":"legacy","title":"Herramientas del cartógrafo","language":"es","rulesEdition":null,"locator":"official:equipment:es:7e70af915a0f0151f102d0a1","verified":false},{"id":"original:493742159b2d9df8e7ad29932e2356d21646fa9d4718b346ea288b8631147169","kind":"legacy","title":"Cartographer's Tools","language":"en","rulesEdition":null,"locator":"official:equipment:eng:dae1c2b890ced263013bd963","verified":false},{"id":"original:62111377c8b2e1b35127d34e6ccf543b87f348ee1ce08f90a7e13fb4005fd83e","kind":"legacy","title":"Cartographer's Tools","language":"en","rulesEdition":null,"locator":"official:equipment:eng:dae1c2b890ced263013bd963","verified":false},{"id":"srd-5.1-es-equipment","kind":"srd","title":"Documento de referencia del sistema 5.1 · edición oficial española","language":"es","rulesEdition":"2014","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1_ES.pdf · página PDF 72 · CC-BY-4.0","verified":true},{"id":"srd-5.1-en-equipment","kind":"srd","title":"Documento de referencia del sistema 5.1 · original inglés","language":"en","rulesEdition":"2014","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1.pdf · página PDF 70 · CC-BY-4.0","verified":true},{"id":"srd-5.1-attribution","kind":"srd","title":"Atribución y licencia del SRD 5.1","language":"es","rulesEdition":"2014","locator":"Esta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es. Adaptaciones: separación de párrafos y tablas, datos estructurados y traducciones propias identificadas en cada bloque.","verified":true},{"id":"srd-5.1-es-tools-context","kind":"srd","title":"SRD 5.1 · herramientas, instrumentos y juegos · español oficial","language":"es","rulesEdition":"2014","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1_ES.pdf · páginas PDF 72–73 · CC BY 4.0","verified":true}],"category":"tool","subtypes":[],"magical":false,"rarity":"none","consumable":false,"properties":[],"weight":{"value":6,"unit":"lb"},"economy":{"basePrice":{"quantity":15,"unit":"gp"},"campaignPrice":null,"explanation":"Precio oficial de 2014. No sobrescribe precios propios de personajes o comerciantes."},"description":[{"id":"official-table","section":"description","provenance":"reviewed-translation","sourceIds":["srd-5.1-en-equipment"],"type":"table","columns":["Objeto","Precio base","Peso"],"rows":[["Herramientas de cartógrafo","15 po","6 lb"]]},{"id":"official-rules-0","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente."},{"id":"tools-context-general","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-tools-context"],"type":"paragraph","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza."}],"requirements":{"attunement":false,"bearer":[],"presence":"possessed","explanation":"No requiere sintonización."},"weapon":null,"armor":null,"resources":[],"capabilities":[{"id":"mundane-use","name":"Uso del objeto","activation":"passive","trigger":"","requirements":{"attunement":false,"bearer":[],"presence":"possessed","explanation":"No requiere sintonización."},"target":"Portador","range":"","duration":"Mientras se cumplen los requisitos.","concentration":false,"costs":[],"consumeQuantity":0,"effects":[{"id":"tool-check","kind":"tool-check","toolKey":"cartographers-tools","condition":""}],"execution":{"mode":"automatic","handler":"equipment-tool-check","explanation":"Prueba de herramienta con característica elegida, competencia, pericia y Talento Seguro cuando corresponden.","pendingAutomation":[]},"textBlockIds":["official-rules-0"]}],"recoverySourceIds":["10bcbc744d950a7244dea4801481756d331519b080af89e385fe7146e37b6475","3e037aff6d87e89591c61912cd78087c5c6cd36f1d7925f2ef8ff0e3938d5957","493742159b2d9df8e7ad29932e2356d21646fa9d4718b346ea288b8631147169","62111377c8b2e1b35127d34e6ccf543b87f348ee1ce08f90a7e13fb4005fd83e"],"review":{"identity":true,"information":false,"editorial":true,"mechanics":false,"unresolved":["Cerrar la cobertura de los datos y diferencias antiguos antes de migrar o retirar versiones; las copias y precios comerciales siguen intactos."]}}$native_96e1f6556455bd29$::jsonb,true),'{features}',$native_2b2bca0e5c7a5789$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$native_2b2bca0e5c7a5789$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:7e70af915a0f0151f102d0a1';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:7ed1857c411cd63b4a9ae3ec' and md5(to_jsonb(t)::text)='33c0fd3de196c769e43317f49bb4ad3c')then raise exception 'NATIVE_DEFINITION_CHANGED:official:equipment:es:7ed1857c411cd63b4a9ae3ec';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(payload,'{rules,definition}',$native_00782f1195daa417${"format":"equipment-definition-draft","schemaVersion":1,"id":"recovery:official:equipment:es:7ed1857c411cd63b4a9ae3ec","revision":1,"language":"es","name":"Ballesta ligera feroz","aliases":["Ballesta ligera Viciosa"],"baseDefinitionId":null,"origin":"official","sources":[{"id":"original:83ba0164acfe3cc773223d31b6b62d5453182ceb21f3e71f917bbe50a839d655","kind":"legacy","title":"Ballesta ligera Viciosa","language":"es","rulesEdition":null,"locator":"official:equipment:es:7ed1857c411cd63b4a9ae3ec","verified":false},{"id":"original:28284928c2516918b68b206c7ac9fa14774f8d3227b604216600806e3823cc04","kind":"legacy","title":"Ballesta ligera Viciosa","language":"es","rulesEdition":null,"locator":"official:equipment:es:7ed1857c411cd63b4a9ae3ec","verified":false},{"id":"original:2cd76210ee0c8b9752842a93af6bd8cc4977ff2a7d09d4657eae1ac9720a9edd","kind":"legacy","title":"Vicious Crossbow, light","language":"en","rulesEdition":null,"locator":"official:equipment:eng:59d682ced2bd798307f98af5","verified":false},{"id":"original:ae0a772f0db6e9a6501f4fb283ec6cad000644caacf50ca309c914095af1e321","kind":"legacy","title":"Vicious Crossbow, light","language":"en","rulesEdition":null,"locator":"official:equipment:eng:59d682ced2bd798307f98af5","verified":false},{"id":"srd-5.1-es-equipment","kind":"srd","title":"SRD 5.1 · edición oficial española","language":"es","rulesEdition":"2014","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1_ES.pdf · páginas PDF 66–68 · CC BY 4.0","verified":true},{"id":"srd-5.1-en-equipment","kind":"srd","title":"SRD 5.1 · original inglés","language":"en","rulesEdition":"2014","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1.pdf · páginas PDF 66 · CC BY 4.0","verified":true},{"id":"srd-5.1-attribution","kind":"srd","title":"Atribución y licencia del SRD 5.1","language":"es","rulesEdition":"2014","locator":"Esta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es.","verified":true},{"id":"dmg-2014-vicious","kind":"book","title":"Dungeon Master’s Guide (2014) · Vicious Weapon","language":"en","rulesEdition":"2014","locator":"https://www.dndbeyond.com/magic-items/5399-vicious-weapon · Legacy","verified":true}],"category":"weapon","subtypes":[],"magical":true,"rarity":"rare","consumable":false,"properties":["ammunition","loading","two-handed","magic"],"weight":{"value":5,"unit":"lb"},"economy":{"basePrice":null,"campaignPrice":null,"explanation":"La tabla describe el objeto mundano base; no fija el precio de la variante mágica. Precios personales y comerciales conservados en los originales."},"description":[{"id":"official-base-table","section":"description","provenance":"reviewed-translation","sourceIds":["srd-5.1-en-equipment"],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)"],"rows":[["Ballesta ligera","25 po","5 lb","1d8 perforante","+0","Munición, Recarga, A dos manos","80/320"]]},{"id":"property-ammunition","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Munición. Solo puedes realizar un ataque a distancia usando un arma con esta propiedad si tienes munición para ella. Cada vez que hagas un ataque, gastarás una unidad de munición. Extraer la munición de una aljaba, un estuche u otro contenedor forma parte del ataque (necesitas una mano libre para cargar un arma a una mano). Al final del combate, podrás recuperar la mitad de la munición usada si dedicas un minuto a buscar en el campo de batalla. Si empleas un arma con esta propiedad para hacer un ataque cuerpo a cuerpo, se considerará un arma improvisada (consulta “Armas improvisadas” en esta misma sección). Además, una honda deberá estar cargada para hacer daño cuando se utilice de esta forma."},{"id":"property-loading","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Recarga. Debido al tiempo que requiere recargar un arma con esta propiedad, cuando utilices una acción, acción adicional o reacción para atacar con ella, solo podrás disparar una unidad de munición, incluso aunque normalmente pudieras hacer más de un ataque."},{"id":"property-two-handed","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"A dos manos. Estas armas requieren el uso de las dos manos."},{"id":"family-rule","section":"rules","provenance":"reviewed-translation","sourceIds":["dmg-2014-vicious"],"type":"paragraph","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma."}],"requirements":{"attunement":false,"bearer":[],"presence":"held","explanation":"No requiere sintonización. La competencia determina los beneficios y restricciones de uso, no es una condición para poseer el objeto."},"weapon":{"category":"simple","meleeReachFeet":null,"thrown":false,"rangeFeet":{"normal":80,"long":320},"attackBonus":0,"damageBonus":0,"baseDamage":[{"id":"base-damage","condition":"","kind":"damage","expression":"1d8","damageType":"piercing","timing":"base"}]},"armor":null,"resources":[],"capabilities":[{"id":"vicious-natural-20","name":"Daño adicional con un 20 natural","activation":"trigger","trigger":"Un 20 natural en la tirada de ataque con esta arma.","requirements":{"attunement":false,"bearer":[],"presence":"held","explanation":"No requiere sintonización. La competencia determina los beneficios y restricciones de uso, no es una condición para poseer el objeto."},"target":"Objetivo impactado","range":"","duration":"Mientras se cumplen los requisitos.","concentration":false,"costs":[],"consumeQuantity":0,"effects":[{"id":"vicious-damage","condition":"Solo con un 20 natural en la tirada de ataque. Es una cantidad fija, no se duplica y no se activa con un crítico obtenido con 19.","kind":"damage","expression":"7","damageType":"piercing","timing":"critical"}],"execution":{"mode":"automatic","handler":"equipment-weapon-hit","explanation":"Daño del arma según el resultado del impacto; los bonos fijos no se duplican en los críticos.","pendingAutomation":[]},"textBlockIds":["family-rule"]}],"recoverySourceIds":["83ba0164acfe3cc773223d31b6b62d5453182ceb21f3e71f917bbe50a839d655","28284928c2516918b68b206c7ac9fa14774f8d3227b604216600806e3823cc04","2cd76210ee0c8b9752842a93af6bd8cc4977ff2a7d09d4657eae1ac9720a9edd","ae0a772f0db6e9a6501f4fb283ec6cad000644caacf50ca309c914095af1e321"],"review":{"identity":true,"information":false,"editorial":true,"mechanics":true,"unresolved":["Cerrar la cobertura de todos los campos originales antes de migrar o retirar versiones."]}}$native_00782f1195daa417$::jsonb,true),'{features}',$native_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen lo