ragraph","text":"Ligera. Un arma ligera es pequeña y fácil de manejar, así que resulta ideal para luchar con dos armas."},{"id":"family-rule","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Puedes utilizar una acción adicional para pronunciar la palabra de activación de esta espada mágica, lo que cubrirá su hoja de llamas. Estas llamas emiten luz brillante en un radio de 12 m y luz tenue 12 m más allá. Mientras la espada esté envuelta en llamas, infligirá 2d6 de daño de fuego adicional a cualquier objetivo al que impacte. Las llamas duran hasta que utilices una acción adicional para volver a pronunciar la palabra de activación o hasta que sueltes o envaines la espada."}],"requirements":{"attunement":true,"bearer":[],"presence":"held","explanation":"Los poderes de la espada requieren sintonización y empuñarla; el uso mundano del arma no concede esos poderes."},"weapon":{"category":"martial","meleeReachFeet":5,"thrown":false,"rangeFeet":null,"attackBonus":0,"damageBonus":0,"baseDamage":[{"id":"base-damage","condition":"","kind":"damage","expression":"1d6","damageType":"piercing","timing":"base"}]},"armor":null,"resources":[],"capabilities":[{"id":"flaming-toggle","name":"Encender o apagar la hoja","activation":"bonus-action","trigger":"","requirements":{"attunement":true,"bearer":[],"presence":"held","explanation":"Los poderes de la espada requieren sintonización y empuñarla; el uso mundano del arma no concede esos poderes."},"target":"Portador","range":"","duration":"Mientras se cumplen los requisitos.","concentration":false,"costs":[],"consumeQuantity":0,"effects":[{"id":"flame-word","condition":"","kind":"narrative","instructions":"Pronunciar la palabra de activación como acción adicional. Emite luz brillante a 40 pies y tenue otros 40 pies; se apaga al soltarla, envainarla o volver a usar la palabra como acción adicional."}],"execution":{"mode":"automatic","handler":"equipment-flame-toggle","explanation":"Activar o apagar las llamas como acción adicional. Se apagan al quitar el arma.","pendingAutomation":[]},"textBlockIds":["family-rule"]},{"id":"flaming-hit","name":"Daño con la hoja encendida","activation":"trigger","trigger":"Impactar con la hoja encendida.","requirements":{"attunement":true,"bearer":[],"presence":"held","explanation":"Los poderes de la espada requieren sintonización y empuñarla; el uso mundano del arma no concede esos poderes."},"target":"Objetivo impactado","range":"","duration":"Mientras se cumplen los requisitos.","concentration":false,"costs":[],"consumeQuantity":0,"effects":[{"id":"flame-damage","condition":"Solo mientras la espada esté encendida mediante su palabra de activación y el ataque impacte.","kind":"damage","expression":"2d6","damageType":"fire","timing":"on-hit"}],"execution":{"mode":"automatic","handler":"equipment-weapon-hit","explanation":"Daño del arma según el resultado del impacto; los bonos fijos no se duplican en los críticos.","pendingAutomation":[]},"textBlockIds":["family-rule"]}],"recoverySourceIds":["5e3b7381ed23acdc9f4e32eac3b0b87ccb4fe3ae6eec680482111d046cb479d3","78b7b05ea1d281be00794c4d24688b584e94b1af4cbd252ea162f1df5266f859","f66e165893103af1fa807ba6d5a58337dc5052ad929a49c07111c08377cea298","6dff1a0999d5803c6c098c16debad6520f44b4ffce5085e53c8207be0a2948cc"],"review":{"identity":true,"information":false,"editorial":true,"mechanics":true,"unresolved":["Cerrar la cobertura de todos los campos originales antes de migrar o retirar versiones."]}}$native_3c1f9d9e10fb093b$::jsonb,true),'{features}',$native_9ddc424fa628a07d$[{"id":"flaming-toggle","kind":"bonus-action","name":"Encender o apagar la hoja","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":true,"description":"Puedes utilizar una acción adicional para pronunciar la palabra de activación de esta espada mágica, lo que cubrirá su hoja de llamas. Estas llamas emiten luz brillante en un radio de 12 m y luz tenue 12 m má